type Row={id:string;url:string;normalized_url:string;title:string;note_source:string;note_search_text:string;is_favorite:number;is_read_later:number;is_read:number;is_archived:number;created_at:string;updated_at:string};
export class BookmarkRepository{
 constructor(private db:Db){}
 private tags(id:string):Tag[]{return this.db.prepare('SELECT t.id,t.name FROM tags t JOIN bookmark_tags bt ON bt.tag_id=t.id WHERE bt.bookmark_id=? ORDER BY t.name COLLATE NOCASE').all(id) as Tag[]}
 private map(row:Row):Bookmark{return {id:row.id,url:row.url,title:row.title,noteSource:row.note_source,tags:this.tags(row.id),isFavorite:!!row.is_favorite,isReadLater:!!row.is_read_later,isRead:!!row.is_read,isArchived:!!row.is_archived,media:{iconUrl:this.hasMedia(row.id,'icon')?`/api/bookmarks/${row.id}/media/icon`:null,previewUrl:this.hasMedia(row.id,'preview')?`/api/bookmarks/${row.id}/media/preview`:null},createdAt:row.created_at,updatedAt:row.updated_at}}
 get(id:string){const row=this.db.prepare('SELECT * FROM bookmarks WHERE id=?').get(id) as Row|undefined;return row?this.map(row):null}
 findByNormalized(normalized:string){const row=this.db.prepare('SELECT * FROM bookmarks WHERE normalized_url=?').get(normalized) as Row|undefined;return row?this.map(row):null}
 list(opts:{view:BookmarkView;q?:string;tag?:string;sort:BookmarkSort}){let rows=this.db.prepare('SELECT * FROM bookmarks').all() as Row[];let pairs=rows.map(row=>({item:this.map(row),noteText:row.note_search_text}));pairs=pairs.filter(({item:b})=>opts.view==='archived'?b.isArchived:!b.isArchived&&(opts.view==='active'||opts.view==='favorites'&&b.isFavorite||opts.view==='read-later'&&b.isReadLater&&!b.isRead));if(opts.tag)pairs=pairs.filter(({item:b})=>b.tags.some(t=>t.name.localeCompare(opts.tag!,undefined,{sensitivity:'accent'})===0));if(opts.q){const ast=parseSearch(opts.q);pairs=pairs.filter(({item,noteText})=>matches(item,ast,noteText))}const items=pairs.map(p=>p.item);items.sort(opts.sort==='title'?(a,b)=>a.title.localeCompare(b.title):opts.sort==='oldest'?(a,b)=>a.createdAt.localeCompare(b.createdAt):(a,b)=>b.createdAt.localeCompare(a.createdAt));return items}
 create(input:BookmarkInput){return this.db.transaction(()=>{const {url,normalizedUrl}=normalizeUrl(input.url);const id=crypto.randomUUID(),now=new Date().toISOString();this.db.prepare('INSERT INTO bookmarks(id,url,normalized_url,title,note_source,note_search_text,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)').run(id,url,normalizedUrl,input.title.trim(),input.noteSource||'',noteToText(input.noteSource||''),now,now);this.setTags(id,input.tags||[]);return this.get(id)!})()}
 update(id:string,patch:BookmarkPatch){return this.db.transaction(()=>{const old=this.get(id);if(!old)return null;const state={url:old.url,title:old.title,noteSource:old.noteSource,tags:old.tags.map(t=>t.name),isFavorite:old.isFavorite,isReadLater:old.isReadLater,isRead:old.isRead,isArchived:old.isArchived,...patch};if(patch.isReadLater===false)state.isRead=false;if(patch.isReadLater===true&&old.isReadLater===false&&patch.isRead===undefined)state.isRead=false;if(patch.isRead===true)state.isReadLater=true;if(patch.isRead===false&&patch.isReadLater===undefined)state.isReadLater=true;const {url,normalizedUrl}=normalizeUrl(state.url);this.db.prepare('UPDATE bookmarks SET url=?,normalized_url=?,title=?,note_source=?,note_search_text=?,is_favorite=?,is_read_later=?,is_read=?,is_archived=?,updated_at=? WHERE id=?').run(url,normalizedUrl,state.title.trim(),state.noteSource,noteToText(state.noteSource),+state.isFavorite,+state.isReadLater,+state.isRead,+state.isArchived,new Date().toISOString(),id);if(patch.tags)this.setTags(id,state.tags);return this.get(id)!})()}
 delete(id:string){return this.db.transaction(()=>{const r=this.db.prepare('DELETE FROM bookmarks WHERE id=?').run(id);this.db.prepare('DELETE FROM tags WHERE NOT EXISTS(SELECT 1 FROM bookmark_tags WHERE tag_id=tags.id)').run();return r.changes>0})()}
 allTags(){return this.db.prepare('SELECT t.id,t.name FROM tags t WHERE EXISTS(SELECT 1 FROM bookmark_tags bt WHERE bt.tag_id=t.id) ORDER BY t.name COLLATE NOCASE').all() as Tag[]}
 private setTags(id:string,tags:string[]){if(tags.length>20)throw new Error('TOO_MANY_TAGS');this.db.prepare('DELETE FROM bookmark_tags WHERE bookmark_id=?').run(id);for(const raw of tags){const name=raw.trim();const norm=name.toLocaleLowerCase();this.db.prepare('INSERT INTO tags(name,normalized_name) VALUES(?,?) ON CONFLICT(normalized_name) DO NOTHING').run(name,norm);const tag=this.db.prepare('SELECT id FROM tags WHERE normalized_name=?').get(norm) as {id:number};this.db.prepare('INSERT INTO bookmark_tags VALUES(?,?)').run(id,tag.id)}this.db.prepare('DELETE FROM tags WHERE NOT EXISTS(SELECT 1 FROM bookmark_tags WHERE tag_id=tags.id)').run()}
 saveMedia(bookmarkId:string,kind:'icon'|'preview',type:string,bytes:Buffer,sourceUrl:string){this.db.prepare('INSERT INTO media_assets(id,bookmark_id,kind,content_type,bytes,source_url,created_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(bookmark_id,kind) DO UPDATE SET content_type=excluded.content_type,bytes=excluded.bytes,source_url=excluded.source_url,created_at=excluded.created_at').run(crypto.randomUUID(),bookmarkId,kind,type,bytes,sourceUrl,new Date().toISOString())}
 media(bookmarkId:string,kind:string){return this.db.prepare('SELECT content_type,bytes FROM media_assets WHERE bookmark_id=? AND kind=?').get(bookmarkId,kind) as {content_type:string;bytes:Buffer}|undefined}
 private hasMedia(id:string,kind:string){return !!this.db.prepare('SELECT 1 FROM media_assets WHERE bookmark_id=? AND kind=?').get(id,kind)}
}
